const AGAYA_COORDS=[11.26694,78.39389],HEIGHT_COMPARISONS=[{name:"Agaya Gangai",heightMeters:91,note:"~300 ft (91m) sheer single drop"},{name:"Tirathgarh Falls",heightMeters:91,note:"Chhattisgarh's multi-tiered falls, for comparison"},{name:"Qutub Minar (Delhi)",heightMeters:73,note:"Tallest brick minaret in the world"},{name:"Jog Falls (Karnataka)",heightMeters:253,note:"India's highest un-tiered waterfall"}],ROUTE_STAGES=[{stage:"1",title:"Temple Start",img:"https://images.unsplash.com/photo-1600100397608-f956e3746c81?auto=format&fit=crop&q=80&w=800",alt:"A South Indian hilltop temple courtyard, the starting point of a forest trek",text:"The trek begins at the Arapaleeswarar Temple atop the Kolli Hills, reached by road via the ghat's 70 hairpin bends. Parking and basic facilities are available near the temple."},{stage:"2",title:"The Staircase",img:"https://images.unsplash.com/photo-1551632811-561732d1e306?auto=format&fit=crop&q=80&w=800",alt:"A long stone staircase descending through dense green forest on a hillside",text:"From the temple, roughly 1,300 stone steps with railings wind steeply downhill through forest, with resting sheds and small stalls selling tea, buttermilk and herbal soups along the way."},{stage:"3",title:"Boulder Path",img:"https://images.unsplash.com/photo-1502786129293-79981df4e689?auto=format&fit=crop&q=80&w=800",alt:"A rocky, boulder-strewn forest path near the base of a waterfall",text:"About 20 metres before the falls, the paved staircase gives way to a short, uneven path over boulders — the last, roughest stretch, but the thunder of the falls is already audible."},{stage:"4",title:"Falls & Pool",img:"https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&q=80&w=800",alt:"A tall waterfall dropping into a shallow rock pool surrounded by forest",text:"The path ends at a shallow pool facing the falls, where the full 300-foot drop and its spray become visible. An iron chain across the pool lets confident visitors wade to the base, though swimming is discouraged due to strong currents."}],SEASONAL_DATA=[{season:"Monsoon (Jun–Sep)",badgeClass:"badge-monsoon",img:"https://images.unsplash.com/photo-1622401467213-a2fecad55b93?auto=format&fit=crop&q=80&w=600",alt:"A waterfall in heavy, powerful monsoon flow",title:"Full & Forceful",text:"The Aiyaru swells with monsoon rain, sending a heavier, more forceful curtain over the cliff — dramatic to view, though currents in the pool below become stronger."},{season:"Post-Monsoon (Nov–Jan)",badgeClass:"badge-winter",img:"https://images.unsplash.com/photo-1601582589907-f92af5ed9db8?auto=format&fit=crop&q=80&w=600",alt:"A calm, clear waterfall flowing steadily over a rock cliff in cool weather",title:"Clear & Comfortable",text:"Flow steadies into a clear, striking curtain, and cooler weather makes the steep trek far more comfortable. Widely considered the best time to visit."}],GALLERY_IMAGES=[{url:"https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&q=80&w=800",caption:"Agaya Gangai's sheer 300-foot drop into the pool below",category:"Hero Waterfall"},{url:"https://images.unsplash.com/photo-1470770903676-69b98201ea1c?auto=format&fit=crop&q=80&w=800",caption:"View of the falls from the boulder path near its base",category:"Waterfall Viewpoint"},{url:"https://images.unsplash.com/photo-1587582423116-ec07293f0395?auto=format&fit=crop&q=80&w=800",caption:"Dense Eastern Ghats forest covering the Kolli Hills slopes",category:"Kolli Hills Landscape"},{url:"https://images.unsplash.com/photo-1551632811-561732d1e306?auto=format&fit=crop&q=80&w=800",caption:"The forested staircase route leading down from the temple to the falls",category:"Access Route"}],NEARBY_ATTRACTIONS=[{name:"Arapaleeswarar Temple",distance:"1 km",lat:11.2735,lng:78.3975,description:"Hilltop Shiva temple marking the start of the descent to the falls, with parking and basic amenities."},{name:"Siddhar Caves (Korakka & Kalanginatha)",distance:"~2 km",lat:11.265,lng:78.39,description:"Forest caves associated with sages who once practiced traditional herbal medicine here."},{name:"Seekuparai Viewpoint",distance:"~15 km",lat:11.246,lng:78.354,description:"A scenic hilltop lookout over the Kolli Hills valley, popular for sunrise and sunset views."},{name:"Kolli Hills Ghat Road (70 hairpin bends)",distance:"0-30 km",lat:11.226,lng:78.335,description:"The dramatic access road up to Kolli Hills, with 70 numbered hairpin bends across roughly 30 km."}],REFERENCES=[{text:"Wikipedia — Agaya Gangai, Kolli Hills, Namakkal district.",link:"https://en.wikipedia.org/wiki/Agaya_Gangai"},{text:"Tamil Nadu Tourism — Agaya Gangai Waterfalls, Kolli Hills.",link:"https://www.tamilnadutourism.tn.gov.in/"},{text:"Rangan Datta — Agaya Gangai Falls, Kolli Hills, Tamil Nadu (trek account).",link:"https://rangandatta.wordpress.com/2023/06/21/agaya-gangai-falls-kolli-hills-tamil-nadu/"},{text:"Images: Unsplash contributors (used under the Unsplash License for demonstration purposes).",link:"https://unsplash.com/license"}];"undefined"!=typeof module&&module.exports&&(module.exports={AGAYA_COORDS:AGAYA_COORDS,HEIGHT_COMPARISONS:HEIGHT_COMPARISONS,ROUTE_STAGES:ROUTE_STAGES,SEASONAL_DATA:SEASONAL_DATA,GALLERY_IMAGES:GALLERY_IMAGES,NEARBY_ATTRACTIONS:NEARBY_ATTRACTIONS,REFERENCES:REFERENCES});